const attempt = 1;
const rawResponse = $json;
const logsDir = 'D:\\ForgeViewAI\\state\\logs';
const rawPath = logsDir + '\\openai_raw_response.json';
const logPath = logsDir + '\\shorts_json_validation.log';
const previousPath = logsDir + '\\previous_valid_shorts_package.json';

function writeLog(message) {
  try {
    const fs = require('fs');
    fs.mkdirSync(logsDir, { recursive: true });
    fs.appendFileSync(logPath, `[${new Date().toISOString()}] ${message}\n`, 'utf8');
  } catch (error) {}
}

function writeJson(path, value) {
  try {
    const fs = require('fs');
    fs.mkdirSync(logsDir, { recursive: true });
    fs.writeFileSync(path, JSON.stringify(value, null, 2), 'utf8');
  } catch (error) {}
}

function cleanString(value) {
  return String(value || '').replace(/\s+/g, ' ').trim();
}

function selectStructuredCandidate(raw) {
  const candidates = [raw.output, raw.text, raw.response, raw.result, raw.data, raw];
  for (const candidate of candidates) {
    if (candidate && typeof candidate === 'object' && !Array.isArray(candidate)) return candidate;
  }
  return null;
}

function validatePackage(value) {
  const errors = [];
  if (!value || typeof value !== 'object' || Array.isArray(value)) errors.push('Package must be a structured object, not free-form text');
  const pkg = value || {};
  for (const key of ['title', 'description', 'narration_script']) {
    if (typeof pkg[key] !== 'string' || !pkg[key].trim()) errors.push(`${key} must be a non-empty string`);
  }
  if (!Array.isArray(pkg.scene_narrations) || pkg.scene_narrations.length !== 7) errors.push('scene_narrations must contain exactly 7 strings');
  if (!Array.isArray(pkg.video_prompts) || pkg.video_prompts.length !== 7) errors.push('video_prompts must contain exactly 7 strings');
  if (!Array.isArray(pkg.tags) || pkg.tags.length < 1) errors.push('tags must contain at least 1 string');
  for (const [name, arr] of [['scene_narrations', pkg.scene_narrations], ['video_prompts', pkg.video_prompts], ['tags', pkg.tags]]) {
    if (Array.isArray(arr)) {
      arr.forEach((item, index) => {
        if (typeof item !== 'string' || !item.trim()) errors.push(`${name}[${index}] must be a non-empty string`);
      });
    }
  }
  if (typeof pkg.title === 'string' && pkg.title.length > 100) errors.push('title must be <= 100 characters');
  return errors;
}

writeJson(rawPath, rawResponse);
const parsed = selectStructuredCandidate(rawResponse);
if (!parsed) {
  const msg = `retry ${attempt}: native OpenAI node did not return a structured object`;
  writeLog(msg);
  return [{ json: { valid: false, attempt, validation_errors: [msg], raw_response_saved_to: rawPath } }];
}

const errors = validatePackage(parsed);
if (errors.length) {
  writeLog(`retry ${attempt}: schema validation failed: ${errors.join('; ')}`);
  return [{ json: { valid: false, attempt, validation_errors: errors, raw_response_saved_to: rawPath } }];
}

const pkg = {
  title: cleanString(parsed.title),
  description: String(parsed.description || '').trim(),
  narration_script: String(parsed.narration_script || '').trim(),
  scene_narrations: parsed.scene_narrations.map(cleanString),
  video_prompts: parsed.video_prompts.map(cleanString),
  tags: parsed.tags.map(cleanString).filter(Boolean),
};

try {
  const staticData = $getWorkflowStaticData('global');
  staticData.last_valid_shorts_package = pkg;
} catch (error) {}
writeJson(previousPath, pkg);
writeLog(`retry ${attempt}: native structured output validation PASS`);
return [{ json: { valid: true, attempt, shorts_json: pkg, shorts_raw: JSON.stringify(pkg, null, 2), validation_errors: [], raw_response_saved_to: rawPath } }];

